import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Introduction & State of the Cephalopod","description":"","frontmatter":{"title":"Introduction & State of the Cephalopod","date":"2026-06-25T00:00:00.000Z","updated":"2026-06-26T00:00:00.000Z","tags":["Ceph","分布式存储","社区动态","会议纪要","开源"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Introduction_State_of_the_Cephalopod.md","filePath":"posts/2026/Introduction_State_of_the_Cephalopod.md","lastUpdated":null}'),n={name:"posts/2026/Introduction_State_of_the_Cephalopod.md"};function l(i,t,s,h,d,p){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="ceph-days-seattle-2026-introduction-state-of-the-cephalopod" tabindex="-1">Ceph Days Seattle 2026：Introduction &amp; State of the Cephalopod <a class="header-anchor" href="#ceph-days-seattle-2026-introduction-state-of-the-cephalopod" aria-label="Permalink to &quot;Ceph Days Seattle 2026：Introduction &amp; State of the Cephalopod&quot;">​</a></h1><h2 id="会议概况" tabindex="-1">会议概况 <a class="header-anchor" href="#会议概况" aria-label="Permalink to &quot;会议概况&quot;">​</a></h2><p>本次演讲是第二届 Ceph Days Seattle 的开场报告，由 Ceph Executive Council 成员、Cisso 公司 CTO <strong>Dan van der Ster</strong> 主讲。Dan 曾在 CERN（欧洲核子研究中心）工作 15 年，深度参与 Ceph 社区超过 14 年，是 Ceph 项目发展历程的重要见证者和推动者。</p><p>开场环节中，Steve 感谢了活动组织者 Lauren Grove 和 Plyo 的 Leanne，并特别表彰了长期贡献 Ceph 项目的社区成员 Dan 和 Anthony 等 Ceph Foundation 大使。</p><h2 id="ceph-的核心存储需求-至今未变" tabindex="-1">Ceph 的核心存储需求（至今未变） <a class="header-anchor" href="#ceph-的核心存储需求-至今未变" aria-label="Permalink to &quot;Ceph 的核心存储需求（至今未变）&quot;">​</a></h2><p>Dan 回顾了 2013 年在 CERN 撰写的一份备忘录——<strong>PB 级通用存储概念验证提案</strong>，其中列出的存储需求在今天看来依然完全适用：</p><ul><li><strong>多协议统一存储</strong>：在同一系统中同时支持 POSIX 文件存储、Block 块存储和 Object 对象存储</li><li><strong>商用硬件</strong>：避免昂贵的专用硬件 RAID，使用 commodity hardware</li><li><strong>无单点故障</strong>：具备 fault tolerance 容错能力</li><li><strong>水平可扩展性</strong>：能够按需增加 capacity 和 IOPS，操作应尽可能简单</li><li><strong>成熟方案</strong>：避免 Not Invented Here 心态，拥抱 open source</li><li><strong>全球多数据中心扩展</strong></li></ul><p>Dan 强调，这些需求定义了现代 scale-out 软件定义基础设施的时代，而 Ceph 正是这一时代的核心存储方案。</p><h2 id="ceph-发展历程回顾" tabindex="-1">Ceph 发展历程回顾 <a class="header-anchor" href="#ceph-发展历程回顾" aria-label="Permalink to &quot;Ceph 发展历程回顾&quot;">​</a></h2><h3 id="早期阶段-2004-2012" tabindex="-1">早期阶段（2004-2012） <a class="header-anchor" href="#早期阶段-2004-2012" aria-label="Permalink to &quot;早期阶段（2004-2012）&quot;">​</a></h3><ul><li><strong>2004 年</strong>：Sage Weil（Ceph 创始人）完成首次 commit，Ceph 诞生。其 PhD 论文的核心目标是替代 Lustre，研究重点是 CephFS 的 metadata 动态分布机制，RADOS 和 CRUSH algorithm 是后续逐步发展的成果</li><li><strong>2010 年左右</strong>：社区成员贡献了 RBD（RADOS Block Device）代码，将 Ceph 从纯文件系统扩展为块存储方案。同期 OpenStack 由 NASA 和 Rackspace 联合发起</li><li><strong>2012 年</strong>：首个稳定版本发布。Sage 创办的 Inktank 公司成立</li></ul><h3 id="关键转折点-2013-2016" tabindex="-1">关键转折点（2013-2016） <a class="header-anchor" href="#关键转折点-2013-2016" aria-label="Permalink to &quot;关键转折点（2013-2016）&quot;">​</a></h3><ul><li><strong>2013 年</strong>：Dan 在 CERN 部署了首个 PB 级 Ceph 集群，初始硬件测试达到 <strong>14 GB/s</strong> 的吞吐量（全部使用 HDD）</li><li><strong>2014 年</strong>：Red Hat 收购 Inktank，成为 Ceph 发展的重大拐点，大幅增加了项目投入</li><li><strong>2015-2016 年</strong>：<strong>BlueStore</strong> 存储后端的开发是最大、最冒险也最成功的投入。此前 FileStore 在 subobject 数量和容量扩展方面存在根本性问题</li><li><strong>2016 年</strong>：Sage 宣布 <strong>&quot;CephFS is now awesome&quot;</strong>——CephFS 的 disaster recovery 和 FSCK 代码完善后达到生产就绪状态</li></ul><h3 id="基金会与社区成熟-2018-至今" tabindex="-1">基金会与社区成熟（2018 至今） <a class="header-anchor" href="#基金会与社区成熟-2018-至今" aria-label="Permalink to &quot;基金会与社区成熟（2018 至今）&quot;">​</a></h3><ul><li><strong>2015-2018 年</strong>：成立 Ceph Advisory Board，协调企业间的贡献和资源</li><li><strong>2018 年</strong>：Ceph Foundation 成立并加入 Linux Foundation，首届 CephCon 举办</li><li><strong>2025 年</strong>：Ceph 项目正式在 Linux Foundation 框架下建立，Ceph Steering Committee 签署并采用 Linux Foundation 技术章程，按 Linux Foundation 规范运作</li></ul><h2 id="ceph-当前状态" tabindex="-1">Ceph 当前状态 <a class="header-anchor" href="#ceph-当前状态" aria-label="Permalink to &quot;Ceph 当前状态&quot;">​</a></h2><h3 id="项目规模" tabindex="-1">项目规模 <a class="header-anchor" href="#项目规模" aria-label="Permalink to &quot;项目规模&quot;">​</a></h3><ul><li><strong>公共遥测数据</strong>：超过 <strong>2 EB</strong> 存储容量，横跨数千个集群（实际规模远超此数字，因多数集群部署在防火墙后无法上报）</li><li><strong>市场覆盖</strong>：超过 90% 的 Open Infrastructure 云平台使用 Ceph；在 Proxmox 和 Kubernetes（通过 Rook）中广泛应用</li><li><strong>完全开源免费</strong>：无许可证锁定，free as in freedom</li></ul><h3 id="版本发布" tabindex="-1">版本发布 <a class="header-anchor" href="#版本发布" aria-label="Permalink to &quot;版本发布&quot;">​</a></h3><ul><li>当前维护两个活跃版本：<strong>Squid</strong> 和 <strong>Tentacle</strong></li><li><strong>Reef 18.2.8</strong> 为最终版本，已正式停止维护，建议用户升级</li><li>支持从两个版本前直接升级（但存在注意事项，建议咨询专业支持）</li><li>下一个版本 <strong>Umbrella</strong> 正在开发中，预计 2027 年 Q1 发布</li></ul><h3 id="tentacle-版本亮点" tabindex="-1">Tentacle 版本亮点 <a class="header-anchor" href="#tentacle-版本亮点" aria-label="Permalink to &quot;Tentacle 版本亮点&quot;">​</a></h3><ul><li><strong>Erasure Coding 性能大幅改善</strong>：2.1 版本已稳定，建议用户在测试环境中验证</li><li>增强了对 <strong>NVMe-oF</strong>（NVMe over Fabrics）和 SAN 的 Gateway 支持</li></ul><h3 id="新增技术作者" tabindex="-1">新增技术作者 <a class="header-anchor" href="#新增技术作者" aria-label="Permalink to &quot;新增技术作者&quot;">​</a></h3><p>Ceph Foundation 新聘技术作者 <strong>Emanuel A</strong>，已发布社区介绍博文，将为项目文档工作提供重要支持。</p><h2 id="社区健康度-lfx-insights-数据" tabindex="-1">社区健康度（LFX Insights 数据） <a class="header-anchor" href="#社区健康度-lfx-insights-数据" aria-label="Permalink to &quot;社区健康度（LFX Insights 数据）&quot;">​</a></h2><p>Dan 展示了 Linux Foundation 的 LFX Insights 工具分析结果：</p><table tabindex="0"><thead><tr><th>指标</th><th>数据</th></tr></thead><tbody><tr><td>GitHub Stars</td><td>2025 年新增约 <strong>2,500</strong> 个 Star，累计持续攀升</td></tr><tr><td>年度 Commit 数</td><td>2025 年约 <strong>60,000</strong> 次，较前一年翻倍</td></tr><tr><td>参与组织数</td><td>约 <strong>190</strong> 个组织贡献代码（峰值为 2019 年的 240 个）</td></tr><tr><td>Pull Requests</td><td>2025 年约 <strong>7,500</strong> 个 PR 被合并</td></tr><tr><td>PR 合并周期</td><td>平均约 <strong>1 个月</strong>（5 天被认领 → 5 天 review → 10 天合并）</td></tr><tr><td>业余时间贡献</td><td>约 <strong>三分之一</strong> 的贡献发生在工作日晚间和周末</td></tr></tbody></table><h2 id="如何参与-ceph" tabindex="-1">如何参与 Ceph <a class="header-anchor" href="#如何参与-ceph" aria-label="Permalink to &quot;如何参与 Ceph&quot;">​</a></h2><ul><li><strong>快速试用</strong>：通过 <code>curl</code> 脚本一键安装，适用于 home lab 或生产环境</li><li><strong>社区资源</strong>：Slack、邮件列表、官方文档</li><li><strong>加入 Ceph Foundation</strong>：代表组织参与，确保项目持续健康发展</li></ul><h2 id="近期社区活动" tabindex="-1">近期社区活动 <a class="header-anchor" href="#近期社区活动" aria-label="Permalink to &quot;近期社区活动&quot;">​</a></h2><table tabindex="0"><thead><tr><th>活动</th><th>地点</th><th>时间</th></tr></thead><tbody><tr><td>Ceph Days Seattle</td><td>西雅图</td><td>已举办</td></tr><tr><td>Ceph Days London</td><td>伦敦</td><td>即将举行</td></tr><tr><td>Meetup</td><td>法兰克福</td><td>计划中</td></tr><tr><td>Ceph Foundation Day</td><td>苏黎世</td><td>2026 年秋季</td></tr><tr><td>CephCon</td><td>待定</td><td>预计 2027 年 Q1</td></tr></tbody></table><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>本次演讲以轻松幽默的方式回顾了 Ceph 从 2004 年 Sage Weil 的 PhD 项目到如今管理 EB 级数据的分布式存储平台的完整历程。核心信息是：Ceph 的设计初衷——统一多协议、商用硬件、无单点故障、水平扩展——在 13 年后依然是存储领域的核心需求。项目正式纳入 Linux Foundation 体系后，社区治理更加规范化，技术贡献持续增长，Ceph 作为开源分布式存储的事实标准地位进一步巩固。</p>',33)])])}const g=e(n,[["render",l]]);export{c as __pageData,g as default};
